def admit_roster_upload_source(source,owner_sources):
    """Complete source and inverse admission only, never a game/compiler gate."""
    tree=ast.parse(source)
    if ast.dump(tree,include_attributes=False)!=EXPECTED_MODULE_AST:
        raise ValueError('complete admitted roster upload continuation source differs')
    if set(owner_sources)!=set(EXPECTED_OWNER_ASTS):
        raise ValueError('all exact roster upload source modules required')
    for path,expected in EXPECTED_OWNER_ASTS.items():
        nodes={node.name:node for node in ast.parse(owner_sources[path]).body if isinstance(node,ast.FunctionDef)}
        for name,source_ast in expected.items():
            if name not in nodes or ast.dump(nodes[name],include_attributes=False)!=source_ast:
                raise ValueError('complete current roster upload owner differs: '+name)
    values={node.targets[0].id:ast.literal_eval(node.value) for node in tree.body
        if isinstance(node,ast.Assign) and len(node.targets)==1 and isinstance(node.targets[0],ast.Name)
        and node.targets[0].id in ('MAIN_ENTRY','MAIN_OWNER','MAIN_MODULE','ORIGINAL_CALLS')}
    definitions=[node for node in tree.body if isinstance(node,ast.FunctionDef) and node.name=='_roster_upload_tree']
    if len(definitions)!=1:raise ValueError('one complete roster upload inverse utility required')
    namespace=dict(ast=ast,copy=copy,_dump=lambda node:ast.dump(node,include_attributes=False),
        EXPECTED_OWNER_ASTS=EXPECTED_OWNER_ASTS,**values)
    exec(compile(ast.Module(body=definitions,type_ignores=[]),'<roster upload source inverse>','exec'),namespace)
    main=ast.parse(owner_sources[values['MAIN_MODULE']])
    derived=namespace['_roster_upload_tree'](main)
    plain_code=compile(main,'<complete original roster Main>','exec',dont_inherit=True)
    derived_code=compile(derived,'<complete cooperative roster Main>','exec',dont_inherit=True)
    name=values['MAIN_OWNER']
    plain=[code for code in plain_code.co_consts if isinstance(code,types.CodeType) and code.co_name==name]
    lifted=[code for code in derived_code.co_consts if isinstance(code,types.CodeType) and code.co_name==name]
    if len(plain)!=1 or len(lifted)!=1 or plain[0].co_flags&32 or not lifted[0].co_flags&32:
        raise ValueError('one genuine original FN and complete derived generator CodeType required')
    return dict(confidence='confirmed_source_only',complete_FN_inverse=True,whole_module_inverse=True,
        main_entry=values['MAIN_ENTRY'],actual_caller_return=0x3CE,complete_business_views=1,
        propagated_actual_CALL_sites=5,refresh_pair=(0xAF48,0x54C4),new_algorithm_bodies=0,
        synchronous_owner_pins=sum(map(len,EXPECTED_OWNER_ASTS.values()))-1,
        actual_CodeType_preconditions_prepared=True,normal_DECL_changed=False,new_wait_types=0,new_CALL_slots=0,
        direct_53E6_alias_enabled=False,shared_559E_entry_enabled=False,portrait_family_added=False,
        original_ForceTurnSession_unchanged=True,factory_cold_install_pins='Root owns exact414 integration',
        strict_pending_unchanged=46004,formal_credit=0,game=False,fixture=False,normal_API=False,
        native=False,hash=False,old_replay=False,public_modified=False)
